x = Symbol('x')

def nolim_at(N, D, a):
    """N/D 의 x->a 극한이 (유한값으로) 존재하지 않으면 True"""
    Np, Dp = Poly(expand(N), x), Poly(expand(D), x)
    if Dp.is_zero:
        return True
    G = gcd(Np, Dp)
    D1 = quo(Dp, G)
    return D1.eval(a) == 0

def all_ok(N, D):
    """모든 실수 a 에서 극한이 존재하면 True"""
    Np, Dp = Poly(expand(N), x), Poly(expand(D), x)
    G = gcd(Np, Dp)
    D1 = quo(Dp, G)
    return D1.count_roots() == 0

def S(b, c):
    f = lambda t: t**2 + b*t + c
    out = set()
    # 분모 f(x)-f(x-t) 의 근 r=(t-b)/2 가 1 이거나 f 의 근일 때만 존재.
    cands = set([b + 2])
    for rho in real_roots(Poly(x**2 + b*x + c, x)):
        cands.add(2*rho + b)
    for t in cands:
        if t > 0:
            N = (x - 1)*f(x)
            D = expand(f(x) - f(x - t))
            if all_ok(N, D):
                out.add(t)
    return out

def cand():
    out = set()
    for b in range(-12, 13):
        for c in range(-40, 41):
            d = b*b - 4*c
            # 판별식이 완전제곱수가 아니면 무리수 t 가 집합에 들어가므로 {3,5} 가 될 수 없다
            if d <= 0 or int(sqrt(d))**2 != d:
                continue
            if S(b, c) == {3, 5} and (1 + b + c) > 0:
                out.add(4**2 + 4*b + c)
    return out

def skill():
    b, c = 3, 0
    return 4**2 + 4*b + c

def standard():
    v = cand()
    assert len(v) == 1
    return list(v)[0]

def unique():
    return sorted(cand())
